-- WAYS S production hardening: preferences, admin RPCs, call signaling and block enforcement.
alter table public.user_preferences add column if not exists phone_visible boolean not null default false;
create table if not exists public.call_signals(id uuid primary key default gen_random_uuid(),call_id uuid not null references public.voice_video_calls(id) on delete cascade,from_user uuid not null references auth.users(id) on delete cascade,to_user uuid not null references auth.users(id) on delete cascade,signal_type text not null check(signal_type in ('offer','answer','ice','recording_consent')),payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(from_user<>to_user));
alter table public.call_signals enable row level security;
drop policy if exists "call participants read signals" on public.call_signals;
create policy "call participants read signals" on public.call_signals for select to authenticated using(auth.uid()=from_user or auth.uid()=to_user);
drop policy if exists "call participants send signals" on public.call_signals;
create policy "call participants send signals" on public.call_signals for insert to authenticated with check(auth.uid()=from_user and exists(select 1 from public.voice_video_calls c where c.id=call_id and ((c.caller_id=from_user and c.callee_id=to_user) or (c.caller_id=to_user and c.callee_id=from_user))));
create or replace function public.is_wayss_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
revoke all on function public.is_wayss_admin() from public,anon;
grant execute on function public.is_wayss_admin() to authenticated;
create or replace function public.admin_update_account(target uuid,suspended boolean) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_wayss_admin() then raise exception 'Admin permission required'; end if; update public.profiles set account_status=case when suspended then 'suspended' else 'active' end where id=target; if not found then raise exception 'Account not found'; end if; end; $$;
revoke all on function public.admin_update_account(uuid,boolean) from public,anon;
grant execute on function public.admin_update_account(uuid,boolean) to authenticated;
create or replace function public.admin_set_verification(target uuid,verified boolean,ways_badge boolean) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_wayss_admin() then raise exception 'Admin permission required'; end if; update public.profiles set is_verified=verified,ways_verified=ways_badge where id=target; if not found then raise exception 'Account not found'; end if; end; $$;
revoke all on function public.admin_set_verification(uuid,boolean,boolean) from public,anon;
grant execute on function public.admin_set_verification(uuid,boolean,boolean) to authenticated;
create or replace function public.admin_review_verification(request_id uuid,approved boolean) returns void language plpgsql security definer set search_path=public as $$ declare req public.verification_requests%rowtype; begin if not public.is_wayss_admin() then raise exception 'Admin permission required'; end if; select * into req from public.verification_requests where id=request_id for update; if not found then raise exception 'Request not found'; end if; update public.verification_requests set status=case when approved then 'approved' else 'rejected' end,reviewed_by=auth.uid(),reviewed_at=now() where id=request_id; if approved then update public.profiles set is_verified=true,ways_verified=(req.request_type='ways') where id=req.user_id; end if; end; $$;
revoke all on function public.admin_review_verification(uuid,boolean) from public,anon;
grant execute on function public.admin_review_verification(uuid,boolean) to authenticated;
create or replace function public.admin_review_report(report_id uuid,next_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_wayss_admin() then raise exception 'Admin permission required'; end if; if next_status not in ('reviewing','resolved','dismissed') then raise exception 'Invalid report status'; end if; update public.profile_reports set status=next_status where id=report_id; end; $$;
revoke all on function public.admin_review_report(uuid,text) from public,anon;
grant execute on function public.admin_review_report(uuid,text) to authenticated;
create or replace function public.protect_profile_admin_fields() returns trigger language plpgsql set search_path=public as $$ begin if auth.uid() is not null and not public.is_wayss_admin() then new.is_verified:=old.is_verified;new.ways_verified:=old.ways_verified;new.account_status:=old.account_status;end if;return new;end; $$;
drop trigger if exists protect_profile_admin_fields_trigger on public.profiles;
create trigger protect_profile_admin_fields_trigger before update on public.profiles for each row execute procedure public.protect_profile_admin_fields();
drop policy if exists "profiles are visible to signed in users" on public.profiles;
drop policy if exists "profiles visible unless blocked by profile owner" on public.profiles;
create policy "profiles visible unless blocked by profile owner" on public.profiles for select to authenticated using(id=auth.uid() or not exists(select 1 from public.profile_blocks b where b.blocker_id=profiles.id and b.blocked_id=auth.uid()));
drop policy if exists "create own follow" on public.follows;
create policy "create own follow" on public.follows for insert to authenticated with check(auth.uid()=follower_id and not exists(select 1 from public.profile_blocks b where (b.blocker_id=follower_id and b.blocked_id=following_id) or (b.blocker_id=following_id and b.blocked_id=follower_id)));
drop policy if exists "requesters create follow requests" on public.follow_requests;
create policy "requesters create follow requests" on public.follow_requests for insert to authenticated with check(auth.uid()=requester_id and status='pending' and not exists(select 1 from public.profile_blocks b where (b.blocker_id=requester_id and b.blocked_id=requested_id) or (b.blocker_id=requested_id and b.blocked_id=requester_id)));
drop policy if exists "participants read messages" on public.messages;
create policy "participants read messages" on public.messages for select to authenticated using(((auth.uid()=sender_id and not deleted_for_sender) or (auth.uid()=receiver_id and not deleted_for_receiver)) and not exists(select 1 from public.profile_blocks b where (b.blocker_id=sender_id and b.blocked_id=receiver_id) or (b.blocker_id=receiver_id and b.blocked_id=sender_id)));
